function thirdLargestDistinct(nums: number[]): number {
  let a = -Infinity, b = -Infinity, c = -Infinity;
  for (const x of nums) {
    if (x === a || x === b || x === c) continue;
    if (x > a) { c = b; b = a; a = x; }
    else if (x > b) { c = b; b = x; }
    else if (x > c) c = x;
  }
  return c === -Infinity ? a : c;
}

